	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4852,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4852,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4852:
	.ascii	"A sh:xone constraint on a property shape judges each value node against shapes; a value is projected as a node reference (its own properties live on its separate @graph node) or a literal, so the value schema has nothing to judge and the constraint is dropped."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4852, 260

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4853,@object
