	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4854,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4854,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4854:
	.ascii	"A sh:node constraint on a property shape judges each value node against a shape; a value is projected as a node reference (its own properties live on its separate @graph node) or a literal, so the value schema has nothing to judge and the constraint is dropped."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4854, 261

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4855,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4855,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4855:
	.ascii	"sh:qualifiedValueShape"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4855, 22

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4856,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4856,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4856:
	.ascii	"A sh:qualifiedValueShape constraint counts the value nodes that conform to a shape, which the value schema cannot judge from a node reference; on a node shape, where it is not well-formed, it judges the focus node itself, which an object schema describing the node's properties does not state, so the constraint is dropped."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4856, 323

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4857,@object
