	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4858,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4858,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4858:
