	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4861, 22

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4862,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4862,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4862:
	.ascii	"A custom SPARQL-based constraint component (named in the note) validates through a SPARQL query, which has no closed-world JSON Schema equivalent, so the constraint is dropped."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4862, 176

