	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4878,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4878:
	.ascii	"A property shape whose path is not one predicate (an inverse, sequence, alternative or closure path) constrains no outgoing JSON property of the projected node, so the property shape is dropped."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4878, 194

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4879,@object
