	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4892,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4892,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4892:
	.ascii	"additional-properties-validation-widened"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4892, 40

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4893,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4893,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4893:
	.ascii	"LinkML 1.11 has no per-class equivalent for JSON Schema's additionalProperties policy or schema. Named attributes retain their constraints, but acceptance of unlisted object keys is widened and recorded on the object schema."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4893, 224

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4894,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4894,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4894:
	.ascii	"A JSON Schema contains is stated as a LinkML has_member, which requires one matching member; LinkML 1.11 has no expression for a minContains above 1 or a maxContains, so those match-count bounds are omitted, as is a contains on a schema the projection renders as no slot expression."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4894, 282

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4895,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4895,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4895:
	.ascii	"JSON Schema if/then/else conditional validation has no LinkML 1.11 expression. Independently representable carrier constraints remain, while the conditional relationship is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4895, 181

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4896,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4896,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4896:
	.ascii	"JSON Schema dependentRequired/dependentSchemas validation has no LinkML 1.11 expression. Attribute constraints remain, while cross-property dependencies are omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4896, 165

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4897,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4897,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4897:
	.ascii	"exclusive-bound-validation-widened"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4897, 34

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4898,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4898,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4898:
	.ascii	"LinkML 1.11 exposes inclusive minimum_value/maximum_value bounds but no exclusive numeric bounds. An exclusive JSON Schema bound is projected as the corresponding inclusive bound, widening acceptance at the boundary value."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4898, 222

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4899,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4899,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4899:
	.ascii	"A JSON Schema format does not have an exact, uniformly enforced LinkML 1.11 equivalent. The scalar carrier remains constrained and the format name is retained when representable, while validation semantics are widened."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4899, 218

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4900,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4900,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4900:
	.ascii	"keyword-validation-dropped"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4900, 26

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4901,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4901,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4901:
	.ascii	"A JSON Schema assertion outside the emitter's closed LinkML 1.11 capability table has no sound projection. The assertion is omitted and recorded at its schema location rather than disappearing silently."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4901, 202

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4902,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4902,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4902:
	.ascii	"JSON Schema multipleOf has no LinkML 1.11 numeric expression. The numeric carrier and other representable bounds remain, while divisibility validation is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4902, 162

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4903,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4903,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4903:
	.ascii	"non-scalar-enum-validation-widened"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4903, 34

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4904,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4904,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4904:
	.ascii	"LinkML 1.11 permissible values are scalar identifiers and cannot encode arbitrary JSON object or array enum members. The representable carrier remains, while non-scalar membership validation is widened."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4904, 202

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4905,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4905,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4905:
	.ascii	"JSON Schema minProperties/maxProperties assertions have no LinkML 1.11 class expression. Named attributes and their requiredness remain, while total property-count validation is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4905, 186

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4906,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4906,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4906:
	.ascii	"slot-identity-rehomed"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4906, 21

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4907,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4907,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4907:
	.ascii	"A source JSON property token without a caller-resolvable RDF identity is assigned to a concrete URI under the caller's configured LinkML default prefix. The source token, generated slot name, and assigned identity remain explicit in the projection report."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4907, 255

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4908,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4908,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4908:
	.ascii	"slot-name-policy-dropped"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4908, 24

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4909,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4909,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4909:
	.ascii	"The caller selected LinkML slot-name skipping for a JSON property whose spelling cannot be emitted directly. The single property is omitted and its exact source location remains explicit in the projection diagnostic."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4909, 216

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4910,@object
	.section	.rodata.cst32,"aM",@progbits,32
.Lanon.94405c78b64873a64bd475064fa46f4e.4910:
	.ascii	"string-length-validation-dropped"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4910, 32

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4911,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4911,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4911:
	.ascii	"JSON Schema minLength/maxLength assertions have no LinkML 1.11 slot expression. The string carrier and representable pattern remain, while code-point length validation is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4911, 179

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4912,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4912,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4912:
	.ascii	"tuple-array-validation-widened"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4912, 30

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4913,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4913,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4913:
	.ascii	"LinkML 1.11 lists are homogeneous and cannot preserve JSON Schema prefixItems or position-specific item schemas. The list is projected to a sound common item carrier, widening position-specific validation."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4913, 205

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4914,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4914,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4914:
	.ascii	"JSON Schema unevaluatedProperties/unevaluatedItems assertions depend on applicator evaluation state that LinkML 1.11 does not expose. Representable local constraints remain, while the unevaluated assertion is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4914, 217

