	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4916,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4916,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4916:
	.ascii	"additional-properties-validation-narrowed"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4916, 41

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4917,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4917,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4917:
	.ascii	"GraphQL input objects reject every field not declared by the input type before resolver execution. A JSON Schema object that permits additional properties therefore accepts source keys that the generated GraphQL input type rejects; named fields remain available and the narrowing is recorded on the object schema."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4917, 313

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4918,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4918,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4918:
	.ascii	"array-cardinality-validation-dropped"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4918, 36

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4919,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4919,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4919:
	.ascii	"GraphQL list types have no minimum- or maximum-length expression. The generated list retains its item carrier while JSON Schema minItems/maxItems validation is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4919, 168

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4920,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4920,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4920:
	.ascii	"JSON Schema contains/minContains/maxContains quantifies matching array elements. GraphQL list input coercion has no corresponding predicate, so the item carrier remains while contains validation is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4920, 206

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4921,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4921,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4921:
	.ascii	"JSON Schema if/then/else chooses validation constraints from runtime instance content. GraphQL input object definitions cannot express that conditional relationship; independently representable fields remain while the conditional is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4921, 241

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4922,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4922,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4922:
	.ascii	"custom-scalar-validation-delegated"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4922, 34

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4923,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4923,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4923:
	.ascii	"GraphQL SDL declares a custom scalar name but does not define its parseValue, parseLiteral, or serialization behavior. Validation carried by the caller-named fallback scalar is therefore delegated to application code and is not an exact self-contained SDL projection."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4923, 267

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4924,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4924,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4924:
	.ascii	"JSON Schema dependentRequired/dependentSchemas imposes cross-field validation. GraphQL input object definitions express each field independently and cannot enforce those dependencies, so the relationship is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4924, 215

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4925,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4925,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4925:
	.ascii	"integer-domain-validation-delegated"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4925, 35

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4926,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4926,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4926:
	.ascii	"GraphQL Int accepts only signed 32-bit integers. A JSON Schema integer domain that is not exactly that domain is carried through the caller-named fallback scalar, whose integer acceptance behavior is application-defined."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4926, 220

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4927,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4927,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4927:
	.ascii	"intersection-validation-delegated"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4927, 33

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4928,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4928,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4928:
	.ascii	"General JSON Schema allOf is an intersection of validation sets. GraphQL has no input intersection type, so a non-mergeable intersection is carried through the caller-named fallback scalar and its validation is delegated."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4928, 221

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4929,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4929,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4929:
	.ascii	"keyword-validation-delegated"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4929, 28

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4930,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4930,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4930:
	.ascii	"A JSON Schema assertion outside the emitter's closed GraphQL capability table has no sound SDL expression. Its value is carried through the caller-named fallback scalar and the assertion is recorded rather than silently treated as enforced."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4930, 240

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4931,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4931,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4931:
	.ascii	"negation-validation-delegated"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4931, 29

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4932,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4932,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4932:
	.ascii	"JSON Schema not is a complement of an instance-validation set. GraphQL input types have no complement operator, so the value is carried through the caller-named fallback scalar and negation validation is delegated."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4932, 214

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4933,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4933,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4933:
	.ascii	"nullable-presence-validation-widened"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4933, 36

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4934,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4934,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4934:
	.ascii	"GraphQL uses one nullable field form for both omission and an explicit null. JSON Schema can distinguish required nullable properties from optional non-null properties; either source distinction must be widened when represented by a nullable GraphQL input field."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4934, 262

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4935,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4935,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4935:
	.ascii	"numeric-validation-dropped"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4935, 26

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4936,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4936,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4936:
	.ascii	"GraphQL Int and Float types do not express JSON Schema bounds, exclusive bounds, or multipleOf. The built-in numeric carrier remains while those runtime predicates are omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4936, 176

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4937,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4937,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4937:
	.ascii	"one-of-validation-delegated"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4937, 27

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4938,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4938,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4938:
	.ascii	"JSON Schema oneOf requires exactly one branch to validate. GraphQL has no input union with exactly-one validation semantics, so a non-finite oneOf is carried through the caller-named fallback scalar and exclusivity is delegated."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4938, 228

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4939,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4939,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4939:
	.ascii	"pattern-properties-validation-changed"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4939, 37

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4940,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4940,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4940:
	.ascii	"JSON Schema patternProperties can admit dynamic regex-selected keys and can add conjunctive validation to declared keys. GraphQL input objects instead expose a fixed field set with one type per field, so dynamic keys are narrowed while overlapping declared-field validation may be widened."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4940, 289

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4941,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4941,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4941:
	.ascii	"JSON Schema minProperties/maxProperties counts runtime object keys. GraphQL input object definitions express field requiredness but cannot bound the total supplied-field count."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4941, 176

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4942,@object
	.section	.rodata.cst32,"aM",@progbits,32
.Lanon.94405c78b64873a64bd475064fa46f4e.4942:
	.ascii	"property-name-validation-changed"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4942, 32

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4943,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4943,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4943:
	.ascii	"JSON Schema propertyNames validates every runtime key, including declared properties. GraphQL input objects expose only a fixed declared field set: unknown names are narrowed, while a source property-name rule that rejects a generated declared field is not enforced and may widen acceptance."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4943, 291

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4944,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4944,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4944:
	.ascii	"recursive-input-nullability-relaxed"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4944, 35

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4945,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4945,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4945:
	.ascii	"GraphQL forbids an unbroken cycle of singular non-null input-object fields because no finite value can satisfy it. The emitter makes one deterministic cycle edge nullable and records that required/non-null source constraint at the field location."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4945, 246

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4946,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4946,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4946:
	.ascii	"singleton-list-coercion-widened"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4946, 31

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4947,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4947,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4947:
	.ascii	"GraphQL variable coercion accepts a non-list value for list input and wraps it as a single-element list. JSON Schema array validation rejects that same non-array value, so every generated list input has this explicit coercion widening."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4947, 235

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4948,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4948,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4948:
	.ascii	"string-validation-dropped"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4948, 25

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4949,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4949,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4949:
	.ascii	"GraphQL String has no length, regular-expression, format, or content assertion. The string carrier remains while JSON Schema string predicates are omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4949, 155

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4950,@object
	.section	.rodata.cst32,"aM",@progbits,32
.Lanon.94405c78b64873a64bd475064fa46f4e.4950:
	.ascii	"tuple-array-validation-delegated"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4950, 32

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4951,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4951,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4951:
	.ascii	"JSON Schema prefixItems and closed tuple tails assign schemas by array position. GraphQL lists are homogeneous, so a non-homogeneous tuple is carried through the caller-named fallback scalar and position-specific validation is delegated."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4951, 237

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4952,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4952,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4952:
	.ascii	"JSON Schema unevaluatedProperties/unevaluatedItems depends on applicator evaluation state that GraphQL input coercion does not expose. Representable local fields and items remain while the unevaluated assertion is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4952, 222

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4953,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4953,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4953:
	.ascii	"union-validation-delegated"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4953, 26

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4954,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4954,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4954:
	.ascii	"A JSON Schema anyOf is carried as a @oneOf input object and an output union when every value selects one alternative, by its JSON kind or, among object alternatives, by a required key no other alternative declares. A type-array union, or an anyOf whose alternatives overlap so a value would satisfy several, has no exactly-one-field input GraphQL could coerce it through; it is carried through the caller-named fallback scalar and branch validation is delegated."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4954, 462

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4955,@object
	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.4955,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.4955:
	.ascii	"JSON Schema uniqueItems compares runtime array values for equality. GraphQL list input coercion cannot require pairwise-distinct elements, so item validation remains while uniqueness is omitted."
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.4955, 194

	.type	.Lanon.94405c78b64873a64bd475064fa46f4e.4956,@object
