	.section	.rodata..Lanon.94405c78b64873a64bd475064fa46f4e.5992,"a",@progbits
.Lanon.94405c78b64873a64bd475064fa46f4e.5992:
	.ascii	"malformed pattern: unescaped '[' inside a character class -- XML Schema Part 2 Appendix G's charGroup defines no nested character class there, so regex-syntax's nested-class union is a different language; a literal '[' must be escaped as '\\['"
	.size	.Lanon.94405c78b64873a64bd475064fa46f4e.5992, 242

